<?php
require __DIR__.'/bootstrap.php';
require __DIR__.'/account.php';
header('Cache-Control: no-store');
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf();
 if(isset($_POST['initialize'])){
  try{store_state(function($s){rate_limit($s,'initialize',10);return $s;});save_admin_password((string)($_POST['newPassword']??''),(string)($_POST['confirmPassword']??''),'',true);header('Location: admin.php');exit;}catch(InvalidArgumentException $ex){$error=$ex->getMessage();}catch(Throwable $ex){error_log((string)$ex);$error='Không thể tạo quản trị. Kiểm tra quyền ghi thư mục data.';}
 }
 elseif(isset($_POST['logout'])){$_SESSION=[];session_regenerate_id(true);header('Location: admin.php');exit;}
 if(!isset($_POST['initialize']))try {
  state(function($s){rate_limit($s,'login',15);return $s;});
  if(password_hash_config()!=='' && password_verify((string)($_POST['password']??''),password_hash_config())){session_regenerate_id(true);$_SESSION['admin']=true;$_SESSION['authHash']=hash('sha256',password_hash_config());header('Location: admin.php');exit;}
  $error='Mật khẩu không đúng.';
 }catch(Throwable $ex){$error='Quá nhiều lần đăng nhập. Vui lòng thử lại sau một giờ.';}
}
try{$s=state();$cardId=card_id();$cardMeta=store_state()['cardMeta'][$cardId];}catch(InvalidArgumentException $ex){http_response_code(404);exit('Không tìm thấy thiệp.');}
